/// <summary>
/// PricingAttribute of table <c>DirPartyTable</c> field NameAlias.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeDirPartyTableNameAlias extends GUPPricingAttributeDirPartyTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(DirPartyTable, NameAlias);
}

    public Set getAllowedValues()
    {
        var           ret = new Set(Types::String);
        DirPartyTable dirPartyTable;

        while select dirPartyTable
            group by NameAlias
        {
            if (! ret.in(dirPartyTable.NameAlias))
            {
                ret.add(dirPartyTable.NameAlias);
            }
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(DirPartyTable, NameAlias));
        qbr.value(queryValue(_value));
    }
